import{_ as d,o as e,c as a,a2 as r}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"월드맵을 어떻게 구성하나","description":"","frontmatter":{},"headers":[],"relativePath":"world/World-Map-Construction.md","filePath":"world/World-Map-Construction.md"}'),o={name:"world/World-Map-Construction.md"};function i(n,t,l,c,h,s){return e(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="월드맵을-어떻게-구성하나" tabindex="-1">월드맵을 어떻게 구성하나 <a class="header-anchor" href="#월드맵을-어떻게-구성하나" aria-label="Permalink to &quot;월드맵을 어떻게 구성하나&quot;">​</a></h1><p><img src="https://github.com/islee23520/seoul-kenshi/blob/main/docs/assets/wiki/isometric-subway-layers.svg?raw=true" alt="지하철 다층 공간의 층과 시야"></p><p>세계 진실은 행정 평면이 아니라 역·층·터널의 그래프다. 이 문서는 그 그래프를 <strong>무엇을 재료로, 어떤 순서로, 어디까지 런타임이 갖고 있는지</strong> 적는다.</p><p><strong>설계 데이터.</strong> 서울 25개 자치구, 이름 있는 역 목록, 주변 시설, 십육국 권역을 빠짐없이 카탈로그로 둔다.</p><p><strong>런타임.</strong> <code>RouteGraph</code>는 영등포—신도림—구로 세 역만 있다. 영등포와 구로는 맞닿지 않는다. Unity <code>Assets</code>에 지리 번들을 넣지 않았다. 문서에 적힌 서울 전역이 게임에 로드된다는 뜻이 아니다.</p><p>관련 문서: <a href="/world/World-and-Subway-Layers.html">서울과 지하철 레이어</a>, <a href="/world/Sixteen-States.html">서울 십육국</a>, <a href="/world/Seoul-Station-Catalog.html">서울 역 카탈로그</a>, <a href="/world/Station-Interior-Construction.html">역 내부에 들어가면</a>, <a href="/rules/Travel-and-Encounters.html">이동과 조우</a>.</p><h2 id="재료" tabindex="-1">재료 <a class="header-anchor" href="#재료" aria-label="Permalink to &quot;재료&quot;">​</a></h2><p>지리 참고는 게임 저장소 밖이다.</p><table tabindex="0"><thead><tr><th>재료</th><th>경로</th><th>쓰는 일</th><th>넣지 않는 일</th></tr></thead><tbody><tr><td>KOSTAT 2013 자치구 25</td><td><a href="seoul-kenshi-data/seoul-geography-20260830/boundaries-kostat-2013/seoul_municipalities_geo.json">KOSTAT GeoJSON</a></td><td>구 폴리곤, 역을 구에 붙이기</td><td>현재 행정 경계로 단정하지 않는다. 기준년 2013.</td></tr><tr><td>OSM PBF</td><td><code>…/osm-current-bbbike/Seoul.osm.pbf</code></td><td>역·시설 점</td><td>GTFS가 없다. 공식 노선도와 1:1이라고 쓰지 않는다.</td></tr><tr><td>OpenFreeMap MVT z14</td><td><code>…/openfreemap/mvt/20260830_080001_pt/14/</code></td><td>도로·철도 타일 357장, bbox <code>126.76,37.42,127.19,37.70</code></td><td>역 내부 격자 에셋이 아니다.</td></tr><tr><td>Mapzen 지형</td><td><code>…/terrain-mapzen-geotiff/</code></td><td>고도</td><td>세계 그래프 노드가 아니다.</td></tr><tr><td>위키 노드 종류</td><td><a href="/world/World-and-Subway-Layers.html">World-and-Subway-Layers.md</a></td><td>Station, StationLayer, SurfaceDistrict, TunnelSegment, VerticalConnector, Interchange, StrategicSite</td><td>런타임 타입으로 아직 없다.</td></tr><tr><td>십육국</td><td><a href="/world/Sixteen-States.html">Sixteen-States.md</a></td><td>권역·정수장·차량기지·시장</td><td>역 명단이 아니다.</td></tr></tbody></table><p>파일별 URL·SHA는 번들 <code>manifest.json</code>에 있다. OSM은 OpenStreetMap 기여자, ODbL 1.0. KOSTAT 2013 라이선스는 저장소 주석만 있고 원 공표 조건을 여기서 재확인하지 않았다.</p><p>전용 지하철 GTFS, 역 내부 메시, 노선별 벡터 레이어는 번들에 없다.</p><h2 id="자치구-25" tabindex="-1">자치구 25 <a class="header-anchor" href="#자치구-25" aria-label="Permalink to &quot;자치구 25&quot;">​</a></h2><p>구 이름은 KOSTAT GeoJSON <code>properties.name</code>이다. 빠짐없다.</p><p>종로구, 중구, 용산구, 성동구, 광진구, 동대문구, 중랑구, 성북구, 강북구, 도봉구, 노원구, 은평구, 서대문구, 마포구, 양천구, 강서구, 구로구, 금천구, 영등포구, 동작구, 관악구, 서초구, 강남구, 송파구, 강동구.</p><p>이 25개가 월드맵의 구 슬롯이다. 십육국은 이 구 위에 권역을 얹는다. 구를 국가로 바꾸지 않는다.</p><h2 id="역-목록" tabindex="-1">역 목록 <a class="header-anchor" href="#역-목록" aria-label="Permalink to &quot;역 목록&quot;">​</a></h2><p>작업 추출: OSM에서 <code>railway=station|halt</code> 또는 <code>station=subway</code>이고 한글 이름이 있는 점을 모아, 구 폴리곤 안에 들어가는 것만 남겼다.</p><ul><li>서울 안 이름 있는 역 <strong>334</strong>. 구 밖·광역 <strong>226</strong>.</li><li>원본 노드 2065, 이름 기준 고유 601(차량기지·경전철·서울 밖 포함).</li><li>구별 수와 좌표는 <a href="/world/Seoul-Station-Catalog.html">서울 역 카탈로그</a>에 있다.</li></ul><p>구별 수(서울 안 334): 강남구 24, 송파구 24, 서초구 21, 중구 19, 강서구 18, 영등포구 18, 동작구 16, 종로구 15, 강동구 14, 노원구 14, 성북구 14, 마포구 13, 강북구 12, 성동구 12, 용산구 12, 광진구 11, 구로구 11, 은평구 11, 서대문구 10, 중랑구 10, 관악구 9, 동대문구 9, 양천구 7, 도봉구 6, 금천구 4.</p><p><strong>미확인.</strong> 334가 서울교통공사·코레일 공표 역 수와 같은지 대조하지 않았다. 환승역/일반역 구분도 OSM 태그만으로는 게임 슬롯 분류가 아니다. 빠진 역·중복 이름·개명 역은 이후 공표 목록과 맞춰야 한다.</p><p>POC 세 역은 이 목록 안에 있다. 영등포(영등포구), 신도림(구로구), 구로(구로구). 런타임 그래프가 이 셋만 연다는 뜻이지, 카탈로그가 셋뿐이라는 뜻이 아니다.</p><h2 id="주변-시설" tabindex="-1">주변 시설 <a class="header-anchor" href="#주변-시설" aria-label="Permalink to &quot;주변 시설&quot;">​</a></h2><p>십육국 문서에 <strong>측정</strong>으로 적힌 이름만 여기서 반복한다. OSM에서 뽑은 편의점·의원 수천 개는 생업 소음이지 거점 슬롯이 아니다.</p><p>정수(서울 안 4, 시외 압력 2): 영등포, 뚝도, 구의, 암사. 강북(남양주), 광암(하남)은 위치는 서울 밖이지만 급수 압력 자산으로 카탈로그에 둔다.</p><p>차량기지(서울 안 8): 신정, 천왕, 방화, 군자, 고덕, 창동, 신내, 수서. 십육국 슬롯 밖 4: 지축, 도봉, 모란, 김포.</p><p>시장 4: 가락시장, 강서시장, 양곡시장, 노량진 수산시장.</p><p>OSM 참고 집계(설계 데이터, 거점 슬롯 아님): 병원·클리닉, 소방서, 경찰, 변전, 철도 조차장 등이 역 좌표 근처에 있다. 역마다 어떤 시설을 슬롯에 넣을지는 <a href="/world/Station-Interior-Construction.html">역 내부에 들어가면</a>에서 정하고, 이 문서는 이름을 빠뜨리지 않는 일만 한다.</p><h2 id="십육국을-구-위에-얹기" tabindex="-1">십육국을 구 위에 얹기 <a class="header-anchor" href="#십육국을-구-위에-얹기" aria-label="Permalink to &quot;십육국을 구 위에 얹기&quot;">​</a></h2><p>국가는 구를 대체하지 않는다. 권역 문장과 핵심 인프라는 <a href="/world/Sixteen-States.html">Sixteen-States.md</a>가 정본이다.</p><table tabindex="0"><thead><tr><th>국가</th><th>등급</th><th>권역</th><th>핵심 인프라</th></tr></thead><tbody><tr><td>여의신정수문정부</td><td>강국</td><td>영등포·양천·여의도 서부 수변축</td><td>영등포 정수, 신정 차량기지, 철도·한강 교량</td></tr><tr><td>서남제작동맹</td><td>강국</td><td>구로·금천 산업축</td><td>제조·수리, 천왕 차량기지, 남서 외곽</td></tr><tr><td>마곡연구평의회</td><td>강국</td><td>강서·마곡·방화 서부 관문축</td><td>연구 인력, 방화 차량기지, 서부 교통·항공 기억</td></tr><tr><td>뚝도공방연합</td><td>강국</td><td>성동·뚝도·성수·군자축</td><td>정수, 성수 공방, 군자 차량기지, 동부 교량</td></tr><tr><td>암사고덕상수단</td><td>강국</td><td>강동·암사·고덕 동부 시계축</td><td>암사 정수, 고덕 차량기지, 동부 교량</td></tr><tr><td>도성기록청</td><td>약소국</td><td>종로·중구·서울역 도성축</td><td>행정기록, 도성 상징, 중앙 재난의료</td></tr><tr><td>용산철도후국</td><td>약소국</td><td>용산 철도·한강 북안</td><td>중앙 철도, 창고, 강변 물류</td></tr><tr><td>노량진남관상회</td><td>약소국</td><td>동작·관악 북부·노량진 시장축</td><td>수산 도매, 냉동, 남부 관문·의료</td></tr><tr><td>상암송신공사</td><td>약소국</td><td>상암·마포·서대문 정보축</td><td>방송·통신, 기록 저장, 서북 관문</td></tr><tr><td>북산피난연맹</td><td>약소국</td><td>은평·성북·강북 북한산 회랑</td><td>피난로, 창고, 고지</td></tr><tr><td>창동차륜방</td><td>약소국</td><td>도봉·노원 북부 관문축</td><td>창동 차량기지, 북부 철도, 주거 쉘</td></tr><tr><td>신내망우환승시</td><td>약소국</td><td>중랑·신내·망우 동북 환승축</td><td>말단 환승, 차량기지, 동북 외곽</td></tr><tr><td>약령의정동맹</td><td>약소국</td><td>동대문·청량리 약령시장축</td><td>약재시장, 동부 의료, 철도</td></tr><tr><td>아차구의관문국</td><td>약소국</td><td>광진·구의·아차산 동부 한강 관문</td><td>구의 정수, 아차산, 동부 교량</td></tr><tr><td>가락잠실배급국</td><td>약소국</td><td>송파·가락·잠실 동남 배급축</td><td>도매시장, 가격 원장, 집결 공간</td></tr><tr><td>수서강남협약도시</td><td>약소국</td><td>강남·서초·수서 남부 연결축</td><td>수서 차량기지, 계약 행정, 남부 외곽</td></tr></tbody></table><p>어느 OSM 역이 어느 국 소유인지는 <strong>미확인</strong>. 점령 규칙은 <a href="/world/Strongholds-and-Territory.html">거점과 영토</a>가 정하고, 이 표는 권역만 고정한다.</p><h2 id="노드와-층" tabindex="-1">노드와 층 <a class="header-anchor" href="#노드와-층" aria-label="Permalink to &quot;노드와 층&quot;">​</a></h2><p>카탈로그의 역 한 곳은 위키에서 <code>Station</code>이다. 그 아래 층은 <code>StationLayer</code>다.</p><table tabindex="0"><thead><tr><th>층</th><th>하는 일</th><th>위험</th></tr></thead><tbody><tr><td>지상 폐허</td><td>채집, 태양광, 관측</td><td>기후, 붕괴</td></tr><tr><td>역사 대합실</td><td>시장, 주거, 행정</td><td>과밀, 화재</td></tr><tr><td>승강장·선로</td><td>이동, 방어, 화물</td><td>병목, 매복</td></tr><tr><td>환승 통로</td><td>노선 사이 정치·물류</td><td>봉쇄, 통행세</td></tr><tr><td>심층 터널</td><td>은밀 이동, 정비</td><td>침수, 통신 단절</td></tr><tr><td>차량기지 인접</td><td>수리, 대형 저장</td><td>공성, 화재</td></tr></tbody></table><p>연결은 지워지지 않는다. 상태만 바뀐다: 정상, 위험, 통제, 봉쇄, 침수, 붕괴, 임시 보수. <a href="/world/Logistics-and-Infrastructure.html">물류와 기반 시설</a>.</p><p>런타임 <code>HeightmapDomain.LayerId</code>(지상/B1/B2/B3)는 전투 지형 높이다. 위 여섯 층을 세계 그래프로 돌리는 코드가 아니다. 둘을 같은 enum으로 합치지 않는다.</p><p>칸 문법: <code>GridCoord</code>, <code>CardinalDirection</code>(북·동·남·서). 한 칸 1.5m / 1.5 Unity 유닛은 <code>GenreContract.json</code>에 있다. 탐색과 전투와 역 내부가 이 칸을 공유한다. 대각은 거절한다.</p><h2 id="지금-코드가-아는-그래프" tabindex="-1">지금 코드가 아는 그래프 <a class="header-anchor" href="#지금-코드가-아는-그래프" aria-label="Permalink to &quot;지금 코드가 아는 그래프&quot;">​</a></h2><p>파일: <code>Game/Assets/Janseon/Core/RouteDomain.cs</code> <code>CreateYeongdeungpoSindorimGuro</code>.</p><ul><li>역: Yeongdeungpo, Sindorim, Guro.</li><li>변: 영등포—신도림, 신도림—구로. 영등포—구로 없음.</li><li>거절: SameNode, UnknownNode, NotAdjacent.</li><li>확인된 이동: 틱 +1, 자원 -2.</li></ul><p>캠페인 단계: 거점 준비 → 원정 → 조우 → 해결 → 정산 → 복귀. <code>CampaignDomain.cs</code>. 정산은 조우 결과를 한 번만 반영한다. 역 내부를 짓지 않는다.</p><h2 id="조립-순서-설계-아직-파이프라인-없음" tabindex="-1">조립 순서 (설계, 아직 파이프라인 없음) <a class="header-anchor" href="#조립-순서-설계-아직-파이프라인-없음" aria-label="Permalink to &quot;조립 순서 (설계, 아직 파이프라인 없음)&quot;">​</a></h2><p>런타임이 서울 전역을 열 때 이 순서를 따른다. 지금은 문서 계약이다.</p><ol><li>구 25 폴리곤을 읽는다. 구 슬롯을 만든다. 십육국 권역 태그를 구에 붙인다.</li><li>역 카탈로그를 읽는다. 각 행을 <code>Station</code>으로 만든다. 구에 소속시킨다.</li><li>OSM·MVT의 선로·환승을 <code>TunnelSegment</code>·<code>Interchange</code> 후보로 올린다. 출처를 <code>measured</code> / <code>derived</code> / <code>fictional</code>로 남긴다.</li><li>정수장·차량기지·시장을 <code>StrategicSite</code>로 붙인다. 가장 가까운 역과 수직 연결을 적는다.</li><li>각 <code>Station</code>에 여섯 <code>StationLayer</code>를 단다. 없는 층은 비활성이지 삭제 아니다.</li><li>연결 기본값은 정상. 봉쇄·침수는 사건으로만 바뀐다.</li><li>POC 세 역만 <code>RouteGraph</code>에 넣는다. 나머지는 데이터로 두고 화면에 안 연다. 전 서울을 한 번에 메시로 올리지 않는다.</li></ol><p>화면은 지금 필요한 노선만 그린다. 역을 고르면 같은 그래프에서 4방향 격자를 펼친다. <a href="/rules/Travel-and-Encounters.html">Travel-and-Encounters.md</a>.</p><h2 id="하지-말-것" tabindex="-1">하지 말 것 <a class="header-anchor" href="#하지-말-것" aria-label="Permalink to &quot;하지 말 것&quot;">​</a></h2><ul><li>16국 캠페인이 돌아간다고 쓰지 않는다.</li><li>334역이 공식 전수라고 쓰지 않는다.</li><li>지리 번들을 Unity가 읽는다 쓰지 않는다.</li><li>전투 Heightmap 층을 세계 층과 같은 말로 쓰지 않는다.</li><li>빈 <code>Janseon.World</code> 어셈블리를 미리 만들지 않는다. 두 번째 실제 호출자가 생긴 뒤에 가른다.</li></ul>',47)])])}const m=d(o,[["render",i]]);export{u as __pageData,m as default};
